mapper.select:
select fi.invoice_id as invoiceId, fi.invoice_no as invoiceNo, fi.invoice_code as invoiceCode, case when fi.invoice_direction = 'sale' then 'sale_invoice' else 'purchase_invoice' end as invoiceType, fi.invoice_type as invoiceCategory, fi.tax_rate as taxRate, coalesce(nullif(fi.source_order_no, ''), fi.invoice_no) as sourceNo, fi.target_name as targetName, ifnull(fi.total_amount, 0) as invoiceAmount, ifnull(fi.amount_without_tax, 0) as amountWithoutTax, ifnull(fi.tax_amount, 0) as taxAmount, fi.invoice_date as billTime from fin_invoice fi
fi.status = 'issued'
and fi.invoice_date >= #{startDate}
and fi.invoice_date <= #{endDate}
order by fi.invoice_date desc, fi.invoice_id desc

select (ifnull((
           select sum(ifnull(so.total_amount, 0))
           from wms_sale_order so
           where so.status in ('audited', 'closed')
             and ifnull(so.audit_time, so.create_time) >= #{startTime}
             and ifnull(so.audit_time, so.create_time) < #{endTime}
       ), 0) - ifnull((
           select sum(ifnull(sr.total_amount, 0))
           from wms_sale_return sr
           where sr.status = 'audited'
             and ifnull(sr.audit_time, sr.create_time) >= #{startTime}
             and ifnull(sr.audit_time, sr.create_time) < #{endTime}
       ), 0)) as saleAmount,
       ifnull((
           select sum(ifnull(fr.amount, 0))
           from fin_receipt fr
           where ifnull(fr.status, 'normal') = 'normal'
             and coalesce(fr.payment_time, fr.receipt_date, fr.create_time) >= #{startTime}
             and coalesce(fr.payment_time, fr.receipt_date, fr.create_time) < #{endTime}
       ), 0) as receivedAmount,
       (ifnull((
           select sum(ifnull(po.total_amount, 0))
           from wms_purchase_order po
           where po.status in ('1', '2', '3')
             and ifnull(po.purchase_date, po.create_time) >= #{startTime}
             and ifnull(po.purchase_date, po.create_time) < #{endTime}
       ), 0) - ifnull((
           select sum(ifnull(pr.total_amount, 0))
           from wms_purchase_return pr
           where pr.status = 'audited'
             and ifnull(pr.audit_time, pr.create_time) >= #{startTime}
             and ifnull(pr.audit_time, pr.create_time) < #{endTime}
       ), 0)) as purchaseAmount,
       (ifnull((
           select sum(ifnull(soi.quantity, 0) * coalesce(
               nullif((
                   select avg(oi.cost_price_snapshot)
                   from wms_outbound_item oi
                   join wms_outbound o on o.outbound_id = oi.outbound_id
                   where o.status = 'audited'
                     and oi.product_id = soi.product_id
                     and oi.cost_price_snapshot > 0
                     and (o.sale_order_id = so.sale_order_id or (o.sale_order_id is null and o.source_order_no = so.order_no))
               ), 0),
               ifnull(mp.cost_price, 0)
           ))
           from wms_sale_order_item soi
           join wms_sale_order so on soi.sale_order_id = so.sale_order_id
           left join md_product mp on soi.product_id = mp.product_id
           where so.status in ('audited', 'closed')
             and ifnull(so.audit_time, so.create_time) >= #{startTime}
             and ifnull(so.audit_time, so.create_time) < #{endTime}
       ), 0) - ifnull((
           select sum(ifnull(sri.quantity, 0) * coalesce(nullif(sri.cost_price_snapshot, 0), ifnull(mp.cost_price, 0)))
           from wms_sale_return_item sri
           join wms_sale_return sr on sri.sale_return_id = sr.sale_return_id
           left join md_product mp on sri.product_id = mp.product_id
           where sr.status = 'audited'
             and ifnull(sr.audit_time, sr.create_time) >= #{startTime}
             and ifnull(sr.audit_time, sr.create_time) < #{endTime}
       ), 0)) as saleCostAmount
